PAGES = {'scan': 'Live scan', 'explorer': 'Attack path explorer', 'agents': 'Agents', 'input': 'Input data', 'analytics': 'Analytics', 'notifications': 'Notifications'}
VIS_CDN = "https://unpkg.com/vis-network@9.1.9/standalone/umd/vis-network.min.js"
CHART_CDN = "https://cdn.jsdelivr.net/npm/chart.js@4.4.4/dist/chart.umd.min.js"
MAIN_PATCH = "from app.api import v21 as _v21_api  # v2.1 kit\napp.include_router(_v21_api.router, prefix=\"/api\")\n"
GITIGNORE = [".env", "data/outbox/", "data/output/", "data/input/", ".v21_backup/"]


def say(ok, msg):
    print(("  [OK]   " if ok else "  [TODO] ") + msg)


def backup(path, stamp):
    if path.exists():
        dest = ROOT / ".v21_backup" / stamp / path.relative_to(ROOT)
        dest.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(path, dest)


def write(rel, text, stamp):
    path = ROOT / rel
    if path.exists() and path.read_text(encoding="utf-8", errors="replace") == text:
        return False
    backup(path, stamp)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8", newline="\n")
    return True


def find_script_src(keyword):
    for html in sorted((ROOT / "static").glob("*.html")):
        m = re.search(r'<script[^>]+src="([^"]*%s[^"]*)"' % re.escape(keyword), html.read_text(encoding="utf-8", errors="replace"), re.I)
        if m:
            return m.group(1)
    return None


def build_page(name, title):
    template = None
    for cand in ("alerts.html", "index.html", "audit.html"):
        p = ROOT / "static" / cand
        if p.exists():
            template = p.read_text(encoding="utf-8")
            break
    extra = ""
    if name == "explorer":
        extra = '<script src="%s"></script>\n' % (find_script_src("vis-network") or VIS_CDN)
    if name == "analytics":
        extra = '<script src="%s"></script>\n' % (find_script_src("chart") or CHART_CDN)
    module = '<script type="module" src="/js/%s.js"></script>' % name
    if template and re.search(r'<script[^>]*type="module"[^>]*></script>', template):
        html = re.sub(r"<title>.*?</title>", "<title>IdentityShield · %s</title>" % title, template, count=1, flags=re.S)
        html = re.sub(r'<script[^>]*src="[^"]*(vis-network|chart)[^"]*"[^>]*></script>\s*', "", html, flags=re.I)
        html = re.sub(r'<script[^>]*type="module"[^>]*></script>', lambda m: extra + module, html, count=1)
        return html
    return ('<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">\n'
            '<title>IdentityShield · %s</title>\n<script src="https://cdn.tailwindcss.com"></script>\n'
            "<script>tailwind.config={theme:{extend:{fontFamily:{sans:['Inter','system-ui','sans-serif'],mono:['JetBrains Mono','monospace']},"
            "colors:{bg:'#0B0F17',panel:'#111827',panel2:'#161E2E',line:'#1F2A3C',muted:'#8A97AD',ink:'#E6EBF2',brand:'#3B82F6',brand2:'#22D3EE',"
            "ok:'#10B981',warn:'#F59E0B',high:'#F97316',crit:'#EF4444'}}}}</script>\n<link rel=\"stylesheet\" href=\"/css/app.css\">\n</head>\n"
            '<body class="bg-bg text-ink font-sans antialiased"><div id="app"></div>\n%s%s\n</body></html>\n') % (title, extra, module)


def status():
    print("\nIntegration status")
    main = (ROOT / "app" / "main.py").read_text(encoding="utf-8") if (ROOT / "app" / "main.py").exists() else ""
    say("_v21_api" in main, "app/main.py includes the v2.1 router")
    pipe = (ROOT / "app" / "pipeline.py").read_text(encoding="utf-8") if (ROOT / "app" / "pipeline.py").exists() else ""
    steps = len(re.findall(r"trace\.step\(", pipe))
    say(steps >= 8, "app/pipeline.py traced steps: %d (want 9+; PROMPT A)" % steps)
    say("input_mode" in pipe, "app/pipeline.py run_pipeline(..., input_mode=...) (PROMPT A)")
    layout = (ROOT / "static" / "js" / "layout.js").read_text(encoding="utf-8") if (ROOT / "static" / "js" / "layout.js").exists() else ""
    say(all(p + ".html" in layout for p in PAGES), "sidebar links to the 6 new pages (PROMPT B)")
    cfg = (ROOT / "app" / "config.py").read_text(encoding="utf-8")
    say("# v2 additions" in cfg and "# v2.1 additions" in cfg, "app/config.py has the v2 and v2.1 blocks")
    missing = [rel for rel in FILES if not (ROOT / rel).exists()]
    say(not missing, "all %d kit files present%s" % (len(FILES), "" if not missing else " (missing: %s)" % ", ".join(missing[:5])))


def main():
    if not (ROOT / "app" / "models.py").exists() or not (ROOT / "static").is_dir():
        print("Run this from the IdentityShield project root (where app/ and static/ are).")
        return 2
    if "--check" in sys.argv:
        status()
        return 0
    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    print("Installing IdentityShield v2.1 kit (backups in .v21_backup/%s/)" % stamp)
    for d in ("app/api", "tests", "tools", "static/js", "static/mock"):
        (ROOT / d).mkdir(parents=True, exist_ok=True)
    for pkg in ("tests", "tools"):
        init = ROOT / pkg / "__init__.py"
        if pkg == "tests" and not init.exists():
            init.write_text("", encoding="utf-8")
    changed = sum(write(rel, text, stamp) for rel, text in FILES.items())
    print("  files written/updated:", changed, "of", len(FILES))

    cfg_path = ROOT / "app" / "config.py"
    cfg = cfg_path.read_text(encoding="utf-8")
    add = ""
    if "# v2 additions" not in cfg:
        add += "\n\n" + CONFIG_V2
    if "# v2.1 additions" not in cfg:
        add += "\n\n" + CONFIG_V21
    if add:
        backup(cfg_path, stamp)
        cfg_path.write_text(cfg.rstrip() + add, encoding="utf-8", newline="\n")
    say(True, "app/config.py blocks present")

    for name, title in PAGES.items():
        write("static/%s.html" % name, build_page(name, title), stamp)
    say(True, "pages: " + ", ".join(n + ".html" for n in PAGES))

    if not (ROOT / ".env.example").exists():
        (ROOT / ".env.example").write_text(ENV_EXAMPLE, encoding="utf-8")
    gi = ROOT / ".gitignore"
    lines = gi.read_text(encoding="utf-8").splitlines() if gi.exists() else []
    new = [g for g in GITIGNORE if g not in lines]
    if new:
        gi.write_text("\n".join(lines + new) + "\n", encoding="utf-8")
    say(True, ".env.example and .gitignore")

    main_path = ROOT / "app" / "main.py"
    text = main_path.read_text(encoding="utf-8")
    if "_v21_api" not in text:
        mounts = [m.start() for m in re.finditer(r"^app\.mount\(", text, re.M)]
        if len(mounts) == 1:
            backup(main_path, stamp)
            main_path.write_text(text[:mounts[0]] + MAIN_PATCH + "\n" + text[mounts[0]:], encoding="utf-8", newline="\n")
            say(True, "app/main.py: v2.1 router included before the static mount")
        else:
            say(False, "app/main.py: add these 2 lines just BEFORE app.mount(...):\n" + MAIN_PATCH)
    else:
        say(True, "app/main.py already includes the v2.1 router")

    bad = []
    for rel in FILES:
        if rel.endswith(".py"):
            try:
                py_compile.compile(str(ROOT / rel), doraise=True)
            except py_compile.PyCompileError as exc:
                bad.append("%s: %s" % (rel, exc))
    say(not bad, "Python files compile" + ("" if not bad else ":\n    " + "\n    ".join(bad)))
    try:
        sys.path.insert(0, str(ROOT))
        import app.api.v21  # noqa: F401
        say(True, "app.api.v21 imports (FastAPI router OK)")
    except Exception as exc:  # noqa: BLE001
        say(False, "app.api.v21 import failed: %s: %s (is your venv active?)" % (type(exc).__name__, exc))
    status()
    print("\nNext: python -m pytest -q   then   python smoke_test.py   then follow FAST_TRACK.md (Prompt A and B).")
    return 0


if __name__ == "__main__":
    sys.exit(main())
